CREATE OR REPLACE FUNCTION public.set_pharmflow_needs_review_photo_v2(p_pharmacy_id uuid, p_review_id uuid, p_photo_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    if auth.uid() is null or not public.is_pharmacy_member(p_pharmacy_id) then
        raise exception 'Pharmacy access required';
    end if;
  perform 1 from public.pharmflow_needs_review_v2 where id=p_review_id and pharmacy_id=p_pharmacy_id and workflow<>'RECEIVING' for update;
  if found then raise exception 'Receiving Needs Review case required'; end if;


    update public.pharmflow_needs_review_v2
       set photo_path = nullif(trim(coalesce(p_photo_path,'')),''),
           updated_at = now()
     where id = p_review_id
       and pharmacy_id = p_pharmacy_id
       and status = 'PENDING';

    return found;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_pharmflow_needs_review_qty_v2(p_pharmacy_id uuid, p_review_id uuid, p_pending_quantity integer)
 RETURNS TABLE(review_id uuid, pending_quantity integer, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_qty integer := greatest(coalesce(p_pending_quantity,1),1);
begin
    if auth.uid() is null or not public.is_pharmacy_member(p_pharmacy_id) then
        raise exception 'Pharmacy access required';
    end if;
  perform 1 from public.pharmflow_needs_review_v2 where id=p_review_id and pharmacy_id=p_pharmacy_id and workflow<>'RECEIVING' for update;
  if found then raise exception 'Receiving Needs Review case required'; end if;


    return query
    update public.pharmflow_needs_review_v2 r
       set pending_quantity = v_qty,
           updated_at = now()
     where r.id = p_review_id
       and r.pharmacy_id = p_pharmacy_id
       and r.status = 'PENDING'
    returning r.id, r.pending_quantity, r.updated_at;

    if not found then
        raise exception 'Pending review item not found';
    end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_pharmflow_needs_review_qty_v3(p_pharmacy_id uuid, p_review_id uuid, p_pending_quantity integer)
 RETURNS TABLE(review_id uuid, pending_quantity integer, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '3s'
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT public.is_pharmacy_member(p_pharmacy_id) THEN RAISE EXCEPTION 'Pharmacy access required'; END IF;
 IF p_pending_quantity IS NULL OR p_pending_quantity<1 THEN RAISE EXCEPTION 'Positive integer quantity required'; END IF;
 PERFORM 1 FROM public.pharmflow_needs_review_v2 r WHERE r.id=p_review_id AND r.pharmacy_id=p_pharmacy_id AND r.workflow='RECEIVING' AND r.status='PENDING' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Pending Receiving review required'; END IF;
 IF EXISTS(SELECT 1 FROM public.pharmflow_needs_review_resolution_intents_v1 i WHERE i.pharmacy_id=p_pharmacy_id AND i.review_id=p_review_id) THEN RAISE EXCEPTION 'Quantity is locked after a resolution request'; END IF;
 RETURN QUERY UPDATE public.pharmflow_needs_review_v2 r SET pending_quantity=p_pending_quantity,updated_at=now()
 WHERE r.id=p_review_id AND r.pharmacy_id=p_pharmacy_id RETURNING r.id,r.pending_quantity,r.updated_at;
END $function$
;

CREATE OR REPLACE FUNCTION public.submit_pharmacy_registration(p_pharmacy_name text, p_pharmacy_code text, p_applicant_name text DEFAULT NULL::text)
 RETURNS TABLE(request_id uuid, request_status text, pharmacy_name text, pharmacy_code text, submitted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user uuid := auth.uid();
    v_email text;
    v_code text;
    v_request uuid;
    v_submitted timestamptz;
begin
    if v_user is null then
        raise exception 'Authentication required';
    end if;

    -- System Owner does not use public registration.
    if public.is_system_owner() then
        raise exception 'System Owner does not need public pharmacy registration';
    end if;

    -- Existing active membership means the user already belongs to a pharmacy.
    if exists (
        select 1
        from public.pharmacy_members m
        join public.pharmacies p on p.id = m.pharmacy_id
        where m.user_id = v_user
          and m.active = true
          and p.status = 'active'
    ) then
        raise exception 'This account already belongs to an active pharmacy';
    end if;

    if nullif(trim(p_pharmacy_name),'') is null then
        raise exception 'Pharmacy name is required';
    end if;

    v_code := upper(
        regexp_replace(
            coalesce(p_pharmacy_code,''),
            '[^A-Za-z0-9_-]+',
            '',
            'g'
        )
    );

    if length(v_code) < 3 then
        raise exception 'Pharmacy code must be at least 3 characters';
    end if;

    -- Prevent requesting a code already owned by an existing pharmacy.
    if exists (
        select 1
        from public.pharmacies p
        where upper(p.code) = v_code
    ) then
        raise exception 'Pharmacy code is already in use';
    end if;

    select lower(email)
    into v_email
    from auth.users
    where id = v_user;

    if v_email is null then
        raise exception 'Authenticated email was not found';
    end if;

    -- Existing pending or approved request is not duplicated.
    if exists (
        select 1
        from public.pharmacy_registration_requests r
        where r.applicant_user_id = v_user
          and r.status in ('pending','approved')
    ) then
        raise exception 'A registration request already exists for this account';
    end if;

    -- A previously rejected user may re-submit using the same request row.
    select r.id
    into v_request
    from public.pharmacy_registration_requests r
    where r.applicant_user_id = v_user
      and r.status = 'rejected'
    order by r.submitted_at desc
    limit 1;

    if v_request is not null then
        update public.pharmacy_registration_requests
        set
            applicant_email = v_email,
            applicant_name = nullif(trim(p_applicant_name),''),
            requested_pharmacy_name = trim(p_pharmacy_name),
            requested_pharmacy_code = v_code,
            status = 'pending',
            submitted_at = now(),
            reviewed_at = null,
            reviewed_by = null,
            review_note = null,
            pharmacy_id = null
        where id = v_request
        returning pharmacy_registration_requests.submitted_at
        into v_submitted;
    else
        insert into public.pharmacy_registration_requests (
            applicant_user_id,
            applicant_email,
            applicant_name,
            requested_pharmacy_name,
            requested_pharmacy_code
        )
        values (
            v_user,
            v_email,
            nullif(trim(p_applicant_name),''),
            trim(p_pharmacy_name),
            v_code
        )
        returning id, pharmacy_registration_requests.submitted_at
        into v_request, v_submitted;
    end if;

    return query
    select
        v_request,
        'pending'::text,
        trim(p_pharmacy_name),
        v_code,
        v_submitted;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_pharmacy_registration_v2(p_requested_pharmacy_code text)
 RETURNS TABLE(request_id uuid, request_status text, pharmacy_code text, submitted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
    v_user uuid := auth.uid();
    v_email text;
    v_code text;
    v_request uuid;
    v_submitted timestamptz;
begin
    if v_user is null then raise exception 'Authentication required'; end if;
    if public.is_system_owner() then raise exception 'System Owner does not need public pharmacy registration'; end if;

    if exists (
        select 1 from public.pharmacy_members m
        join public.pharmacies p on p.id=m.pharmacy_id
        where m.user_id=v_user and m.active=true and p.status='active'
    ) then
        raise exception 'This account already belongs to an active pharmacy';
    end if;

    v_code := upper(regexp_replace(coalesce(p_requested_pharmacy_code,''),'[^A-Za-z0-9_-]+','','g'));
    if length(v_code) < 3 then raise exception 'Pharmacy code must be at least 3 characters'; end if;

    select lower(email) into v_email from auth.users where id=v_user;
    if v_email is null then raise exception 'Authenticated email was not found'; end if;

    if exists (
        select 1 from public.pharmacy_registration_requests r
        where r.applicant_user_id=v_user and r.status in ('pending','approved')
    ) then
        raise exception 'A registration request already exists for this account';
    end if;

    select r.id into v_request
    from public.pharmacy_registration_requests r
    where r.applicant_user_id=v_user and r.status='rejected'
    order by r.submitted_at desc limit 1;

    if v_request is not null then
        update public.pharmacy_registration_requests
        set applicant_email=v_email,
            applicant_name=null,
            requested_pharmacy_name='Pending owner assignment',
            requested_pharmacy_code=v_code,
            status='pending', submitted_at=now(),
            reviewed_at=null, reviewed_by=null, review_note=null, pharmacy_id=null
        where id=v_request
        returning pharmacy_registration_requests.submitted_at into v_submitted;
    else
        insert into public.pharmacy_registration_requests(
            applicant_user_id,applicant_email,applicant_name,requested_pharmacy_name,requested_pharmacy_code
        ) values (
            v_user,v_email,null,'Pending owner assignment',v_code
        ) returning id, pharmacy_registration_requests.submitted_at into v_request,v_submitted;
    end if;

    return query select v_request,'pending'::text,v_code,v_submitted;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.summary_pharmflow_expiry_inventory_v1(p_pharmacy_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare cur integer:=(extract(year from timezone('Asia/Riyadh',now()))::integer*12+extract(month from timezone('Asia/Riyadh',now()))::integer);result jsonb;
begin
 perform pharmflow_expiry_private.valid_auth_session();
 if public.is_pharmacy_member(p_pharmacy_id) is not true then raise exception 'Pharmacy access required';end if;
 select jsonb_agg(jsonb_build_object('key',p.key,'from',p.lo,'to',p.hi,'count',q.n,'units',q.units)) into result
 from (values('EXPIRED',null::integer,cur),('NEXT1',cur+1,cur+1),('NEXT2',cur+1,cur+2),('NEXT6',cur+1,cur+6)) p(key,lo,hi)
 cross join lateral(select count(*) n,coalesce(sum(s.verified_quantity),0) units from public.pharmflow_expiry_current_state_v1 s
 where s.pharmacy_id=p_pharmacy_id and s.status='ACTIVE' and (p.lo is null or s.expiry_year*12+s.expiry_month>=p.lo) and s.expiry_year*12+s.expiry_month<=p.hi) q;
 return result;
end $function$
;

